function shelfItem(shelf, id) { var list = Array.isArray(shelf) ? shelf : []; for (var i = 0; i < list.length; i++) if (list[i] && list[i].id === id) return list[i]; return null; }
/** PLY-001 §3.2: what a child owns that today's face cannot wear. Never hidden, never offered, never taken away — just counted. */
function ownedElsewhere(p, shelf, look) {
  var owned = ownedOf(p), n = 0;
  for (var i = 0; i < owned.length; i++) { var it = shelfItem(shelf, owned[i]); if (it && it.kind === 'face' && !itemFits(it, look)) n++; }
  return n;
}

function today() { var d = new Date(); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }
function appOf(v) { var a = v && typeof v === 'object' ? JSON.parse(JSON.stringify(v)) : {}; if (!Array.isArray(a.profiles)) a.profiles = []; if (!Array.isArray(a.sets)) a.sets = []; if (typeof a.activeId !== 'string') a.activeId = ''; return a; }
function dueCount(model) { var n = 0, now = Date.now(); var sk = (model && model.skills) || {}; for (var id in sk) if (sk[id].m > 0 && sk[id].due && sk[id].due <= now) n++; return n; }
function daysThisWeek(days) { var now = new Date(); var start = new Date(now); start.setDate(now.getDate() - ((now.getDay() + 6) % 7)); var s = start.getFullYear() + '-' + String(start.getMonth() + 1).padStart(2, '0') + '-' + String(start.getDate()).padStart(2, '0'); var n = 0; for (var i = 0; i < (days || []).length; i++) if (days[i] >= s) n++; return n; }
function decorate(p) { var out = JSON.parse(JSON.stringify(p)); out.due = dueCount(p.model); out.days7 = daysThisWeek(p.days); out.answered = (p.model && p.model.answered) || 0; out.faceOptions = wearOptions(p.look, wearOf(p)); return out; }

var STAR_RULE = {"right":1,"finish":5,"level":10,"best":5,"item":2,"list":25};
function withStars(model) {
  if (!model.skills) model.skills = {};
  if (!model.bests || typeof model.bests !== 'object') model.bests = {};
  // PLY-002: what has been spent in the hangar. A model from the RKT-011 pick era has none, so its old picks are never charged for.
  if (typeof model.spent !== 'number' || !(model.spent >= 0)) model.spent = 0;
  if (typeof model.stars === 'number') return model;
  var grant = 0;
  for (var id in model.skills) { var lv = Number(model.skills[id].m) || 0; grant += STAR_RULE.level * lv; model.skills[id].paid = lv; }
  model.stars = grant;
  return model;
}

var MOON = {"species":[{"id":"blob","name":{"en":"Blob","fr":"Blob"},"names":["Zib","Plop","Mimo","Bloop"]},{"id":"bean","name":{"en":"Bean","fr":"Haricot"},"names":["Zorp","Tilly","Nok","Beep"]},{"id":"trio","name":{"en":"Trio","fr":"Trio"},"names":["Trix","Oko","Pip","Lumo"]},{"id":"squid","name":{"en":"Squiggle","fr":"Gribouille"},"names":["Wiggo","Tako","Squee","Flo"]},{"id":"fuzz","name":{"en":"Fuzz","fr":"Poilu"},"names":["Fizz","Puff","Koko","Ruff"]},{"id":"star","name":{"en":"Twinkle","fr":"Étincelle"},"names":["Stella","Zing","Nova","Pix"]}],"colours":[{"id":"lime","token":"--alien-lime","name":{"en":"Lime","fr":"Citron vert"}},{"id":"mint","token":"--alien-mint","name":{"en":"Mint","fr":"Menthe"}},{"id":"sky","token":"--alien-sky","name":{"en":"Sky","fr":"Ciel"}},{"id":"lilac","token":"--alien-lilac","name":{"en":"Lilac","fr":"Lilas"}},{"id":"pink","token":"--alien-pink","name":{"en":"Pink","fr":"Rose"}},{"id":"sunny","token":"--alien-sunny","name":{"en":"Sunny","fr":"Soleil"}}],"foods":[{"id":"strawberry","glyph":"🍓","name":{"en":"Strawberry","fr":"Fraise"},"cost":3},{"id":"cookie","glyph":"🍪","name":{"en":"Cookie","fr":"Cookie"},"cost":4},{"id":"doughnut","glyph":"🍩","name":{"en":"Doughnut","fr":"Beignet"},"cost":5},{"id":"pizza","glyph":"🍕","name":{"en":"Pizza","fr":"Pizza"},"cost":6},{"id":"cheese","glyph":"🧀","name":{"en":"Moon cheese","fr":"Fromage de lune"},"cost":7},{"id":"cake","glyph":"🍰","name":{"en":"Star cake","fr":"Gâteau étoilé"},"cost":8}],"wear":[{"id":"bow","slot":"hat","name":{"en":"Bow","fr":"Nœud"},"cost":20},{"id":"party","slot":"hat","name":{"en":"Party hat","fr":"Chapeau de fête"},"cost":25},{"id":"beanie","slot":"hat","name":{"en":"Bobble hat","fr":"Bonnet"},"cost":30},{"id":"tophat","slot":"hat","name":{"en":"Top hat","fr":"Haut-de-forme"},"cost":45},{"id":"crown","slot":"hat","name":{"en":"Crown","fr":"Couronne"},"cost":80},{"id":"glasses","slot":"eyes","name":{"en":"Glasses","fr":"Lunettes"},"cost":20},{"id":"sunglasses","slot":"eyes","name":{"en":"Sunglasses","fr":"Lunettes de soleil"},"cost":35},{"id":"monocle","slot":"eyes","name":{"en":"Monocle","fr":"Monocle"},"cost":40},{"id":"starglasses","slot":"eyes","name":{"en":"Star glasses","fr":"Lunettes étoiles"},"cost":50},{"id":"scarf","slot":"neck","name":{"en":"Scarf","fr":"Écharpe"},"cost":25},{"id":"bowtie","slot":"neck","name":{"en":"Bow tie","fr":"Nœud papillon"},"cost":30},{"id":"necklace","slot":"neck","name":{"en":"Necklace","fr":"Collier"},"cost":40}],"cost":[0,60,90,120,160,200,240,280,320,360],"max":6,"domes":[{"id":"crater","glyph":"🏠","name":{"en":"Crater Dome","fr":"Dôme du cratère"},"cost":1000,"room":2},{"id":"ridge","glyph":"🏡","name":{"en":"Ridge Dome","fr":"Dôme de la crête"},"cost":1500,"room":2}],"egg":300,"grow":[6,18],"fav":2};
function moonText(bi, lang) { return bi ? (lang === 'fr' ? bi.fr : bi.en) : ''; }
function moonFind(list, id) { for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i]; return null; }
function moonOf(p) {
  var m = p && p.moon && typeof p.moon === 'object' ? p.moon : {};
  var raw = Array.isArray(m.aliens) ? m.aliens.filter(function (a) { return a && typeof a.id === 'string' && a.id; }) : [];
  var aliens = raw.map(function (a) {
    var w = a.wear && typeof a.wear === 'object' ? a.wear : {};
    return { id: a.id, species: moonFind(MOON.species, a.species) ? a.species : MOON.species[0].id, colour: moonFind(MOON.colours, a.colour) ? a.colour : MOON.colours[0].id, name: String(a.name || ''), meals: Math.max(0, Math.floor(Number(a.meals) || 0)), fav: moonFind(MOON.foods, a.fav) ? a.fav : MOON.foods[0].id, found: a.found === true, wear: { hat: typeof w.hat === 'string' ? w.hat : '', eyes: typeof w.eyes === 'string' ? w.eyes : '', neck: typeof w.neck === 'string' ? w.neck : '' } };
  });
  return {
    aliens: aliens,
    sel: typeof m.sel === 'string' ? m.sel : '',
    owned: Array.isArray(m.owned) ? m.owned.filter(function (x) { return typeof x === 'string'; }) : [],
    // TPL-014 M1: every alien ever had (species-colour), for the Alien Book; read as the union with the aliens on the moon,
    // so a moon from before the book opens with what it already has. The domes built.
    met: moonMetOf(m, aliens),
    domes: Array.isArray(m.domes) ? m.domes.filter(function (x) { return !!moonFind(MOON.domes, x); }) : []
  };
}
function moonKey(species, colour) { return species + '-' + colour; }
/** TPL-014 M1: a name to suggest that no alien on this moon already has (the list goes round; then a number). */
function moonFreshName(sp, moon) {
  var taken = moon.aliens.map(function (a) { return String(a.name).toLowerCase(); });
  for (var k = 0; k < sp.names.length; k++) {
    var nm = sp.names[(moon.aliens.length + k) % sp.names.length];
    if (taken.indexOf(nm.toLowerCase()) === -1) return nm;
  }
  var base = sp.names[moon.aliens.length % sp.names.length], at = 2;
  while (taken.indexOf((base + ' ' + at).toLowerCase()) !== -1) at++;
  return base + ' ' + at;
}
function moonMetOf(m, aliens) {
  var met = [];
  var add = function (k) { if (typeof k !== 'string') return; var bits = k.split('-'); if (moonFind(MOON.species, bits[0]) && moonFind(MOON.colours, bits[1]) && met.indexOf(k) === -1) met.push(k); };
  (Array.isArray(m.met) ? m.met : []).forEach(add);
  aliens.forEach(function (a) { add(moonKey(a.species, a.colour)); });
  return met;
}
function moonMax(moon) {
  var n = MOON.max;
  for (var i = 0; i < moon.domes.length; i++) n += (moonFind(MOON.domes, moon.domes[i]) || { room: 0 }).room;
  return n;
}
function moonStage(meals) { return meals >= MOON.grow[1] ? 2 : meals >= MOON.grow[0] ? 1 : 0; }
function moonAlienCost(n) { return n < MOON.cost.length ? MOON.cost[n] : MOON.cost[MOON.cost.length - 1]; }
function moonColour(id) { var c = moonFind(MOON.colours, id) || MOON.colours[0]; return 'var(' + c.token + ')'; }
function moonSelected(moon) { return moonFind(moon.aliens, moon.sel) || moon.aliens[0] || null; }

var app = appOf(Inputs.app);
var id = String(Inputs.profileId || app.activeId);
var action = String(Inputs.action || '');
var ok = false, why = 'noProfile', said = '', alienId = '';
for (var i = 0; i < app.profiles.length; i++) {
  var p = app.profiles[i];
  if (p.id !== id) continue;
  var lang = p.lang === 'fr' ? 'fr' : 'en';
  var fr = lang === 'fr';
  var moon = moonOf(p);
  var model = withStars(JSON.parse(JSON.stringify(p.model || {})));
  var purse = purseOf(model);
  var al = moonFind(moon.aliens, String(Inputs.alienId || '')) || moonSelected(moon);
  why = '';
  if (action === 'adopt') {
    var n = moon.aliens.length;
    var cost = moonAlienCost(n);
    if (n >= moonMax(moon)) why = 'full';
    else if (cost > purse) why = 'tooDear';
    else {
      var sp = moonFind(MOON.species, String(Inputs.species || '')) || MOON.species[0];
      var col = moonFind(MOON.colours, String(Inputs.colour || '')) || MOON.colours[0];
      var nm = String(Inputs.name || '').trim().slice(0, 16) || moonFreshName(sp, moon);
      al = { id: 'a' + Date.now().toString(36) + Math.floor(Math.random() * 1000).toString(36), species: sp.id, colour: col.id, name: nm, meals: 0, fav: MOON.foods[Math.floor(Math.random() * MOON.foods.length)].id, found: false, wear: { hat: '', eyes: '', neck: '' } };
      moon.aliens.push(al);
      if (moon.met.indexOf(moonKey(al.species, al.colour)) === -1) moon.met.push(moonKey(al.species, al.colour));
      model.spent = spentOf(model) + cost;
      said = (fr ? 'Bienvenue sur la Lune, {n} !' : 'Welcome to the moon, {n}!').replace('{n}', nm);
      ok = true;
    }
  } else if (action === 'build') {
    // TPL-014 M1: a dome, built once, makes room for more aliens.
    var dome = moonFind(MOON.domes, String(Inputs.thingId || ''));
    if (!dome) why = 'unknown';
    else if (moon.domes.indexOf(dome.id) !== -1) why = 'owned';
    else if (dome.cost > purse) why = 'tooDear';
    else {
      moon.domes.push(dome.id);
      model.spent = spentOf(model) + dome.cost;
      said = (fr ? '{d} est construit : {r} places de plus sur la Lune !' : 'The {d} is built: room for {r} more aliens!').replace('{d}', moonText(dome.name, lang)).replace('{r}', dome.room);
      ok = true;
    }
  } else if (action === 'egg') {
    // TPL-014 M1: always an alien never had (a species in a colour) while there is one; then any. No rarity, no spin.
    if (moon.aliens.length >= moonMax(moon)) why = 'full';
    else if (MOON.egg > purse) why = 'tooDear';
    else {
      var pool = [];
      for (var es = 0; es < MOON.species.length; es++) for (var ec = 0; ec < MOON.colours.length; ec++) {
        if (moon.met.indexOf(moonKey(MOON.species[es].id, MOON.colours[ec].id)) === -1) pool.push([MOON.species[es], MOON.colours[ec]]);
      }
      if (!pool.length) for (var as = 0; as < MOON.species.length; as++) for (var ac = 0; ac < MOON.colours.length; ac++) pool.push([MOON.species[as], MOON.colours[ac]]);
      var hatch = pool[Math.floor(Math.random() * pool.length)];
      var hsp = hatch[0], hcol = hatch[1];
      var hname = moonFreshName(hsp, moon);
      al = { id: 'a' + Date.now().toString(36) + Math.floor(Math.random() * 1000).toString(36), species: hsp.id, colour: hcol.id, name: hname, meals: 0, fav: MOON.foods[Math.floor(Math.random() * MOON.foods.length)].id, found: false, wear: { hat: '', eyes: '', neck: '' } };
      moon.aliens.push(al);
      if (moon.met.indexOf(moonKey(hsp.id, hcol.id)) === -1) moon.met.push(moonKey(hsp.id, hcol.id));
      model.spent = spentOf(model) + MOON.egg;
      said = (fr ? 'L’œuf éclot : voici {n}, un {s} {c} !' : 'The egg hatched: meet {n}, a {c} {s}!').replace('{n}', hname).replace('{s}', moonText(hsp.name, lang)).replace('{c}', moonText(hcol.name, lang).toLowerCase());
      ok = true;
    }
  } else if (!al) why = 'noAlien';
  else if (action === 'select') ok = true;
  else if (action === 'feed') {
    var food = moonFind(MOON.foods, String(Inputs.foodId || ''));
    if (!food) why = 'unknown';
    else if (food.cost > purse) why = 'tooDear';
    else {
      var before = moonStage(al.meals);
      var loved = food.id === al.fav;
      al.meals += loved ? MOON.fav : 1;
      model.spent = spentOf(model) + food.cost;
      if (loved && !al.found) said = fr ? '{n} ADORE {f} ! C’est son plat préféré : deux repas d’un coup.' : '{n} LOVES {f}! It’s the favourite: two meals in one.';
      else if (loved) said = fr ? '{n} ADORE {f} ! (+2 repas)' : '{n} LOVES {f}! (+2 meals)';
      else said = fr ? '{n} croque {f}. Miam !' : '{n} munches {f}. Yum!';
      if (loved) al.found = true;
      said = said.replace('{n}', al.name).replace('{f}', food.glyph);
      if (moonStage(al.meals) > before) said += (fr ? ' {n} a grandi !' : ' {n} grew!').replace('{n}', al.name);
      ok = true;
    }
  } else if (action === 'buy' || action === 'wear') {
    var item = moonFind(MOON.wear, String(Inputs.wearId || ''));
    var owns = !!item && moon.owned.indexOf(item.id) !== -1;
    if (!item) why = 'unknown';
    else if (action === 'buy' && owns) why = 'owned';
    else if (action === 'wear' && !owns) why = 'notOwned';
    else if (action === 'buy' && item.cost > purse) why = 'tooDear';
    else {
      var thing = moonText(item.name, lang);
      if (action === 'buy') { moon.owned.push(item.id); model.spent = spentOf(model) + item.cost; }
      if (action === 'wear' && al.wear[item.slot] === item.id) {
        al.wear[item.slot] = '';
        said = (fr ? '{n} enlève : {i}.' : '{n} takes off the {i}.').replace('{n}', al.name).replace('{i}', fr ? thing : thing.toLowerCase());
      } else {
        al.wear[item.slot] = item.id;
        said = (fr ? 'Et voilà : {i} pour {n} !' : '{n} is wearing the {i}!').replace('{n}', al.name).replace('{i}', fr ? thing : thing.toLowerCase());
      }
      ok = true;
    }
  } else why = 'action';
  if (why === 'tooDear') said = fr ? 'Pas encore assez d’étoiles : une partie en rapporte !' : 'Not enough stars yet: a game earns more!';
  if (ok) {
    if (al) moon.sel = al.id;
    p.model = model;
    p.moon = moon;
    alienId = al ? al.id : '';
  }
}
Outputs.app = app;
Outputs.ok = ok;
Outputs.why = why;
Outputs.said = said;
